def remove_Occ(text, char):
    # Remove all occurrences of 'char' from the beginning of the text
    while text.startswith(char):
        text = text[1:]

    # Remove all occurrences of 'char' from the end of the text
    while text.endswith(char):
        text = text[:-1]

    return text

# Test case to verify the solution
assert remove_Occ("hello", "l") == "heo"

