def remove_Occ(s,c):
    # Removing the first occurrence of c from s
    while c in s:
        s = s[:s.index(c)] + s[s.index(c)+1:]

    # Removing the last occurrence of c from s
    if c in s:
        s = s[:s.rindex(c)]

    return s

# Example test case
