def find_Product(arr, n):
    # Initialize the variables
    prod = 1
    freq = {}

    # Calculate frequency of each element
    for i in range(n):
        if arr[i] in freq:
            freq[arr[i]] += 1
        else:
            freq[arr[i]] = 1

    # Find the product of non-repeated elements
    for key in freq:
        if freq[key] == 1:
            prod *= key

    return prod

