def binomial_coeff(n, k):
    # Calculate binomial coefficient using Pascal's Triangle formula
    if k > n - k:
        k = n - k

    result = 1
    for i in range(k + 1, n + 1):
        result *= i
    for i in range(2, k + 1):
        result //= i

    return result

