def find_Nth_Digit(x, y, n):
    # Calculate the total number of digits in all fractions from x/y to (x+1)/y
    total_digits = 0
    for numerator in range(x + 1):
        for denominator in range(numerator + 1, y + 1):
            # Convert the fraction to string and count each digit
            total_digits += len(str(numerator / denominator))

    # Calculate the position of the nth digit by dividing (n - 1) by the total number of digits
    index = ((n - 1) // total_digits)

    # Find the fraction where the nth digit is located
    for numerator in range(x, y + 1):
        for denominator in range(numerator + 1, y + 1):
            if numerator / denominator >= index:
                break

    # Return the nth digit of the fraction
    return int(str(numerator / denominator)[index])

