def rearrange_string(s):
    # Dictionary to count occurrences of each character
    char_count = {}

    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Check if any character occurs more than half the length of the string
    max_count = 0
    for count in char_count.values():
        if count > max_count:
            max_count = count

    if max_count > (len(s) + 1) // 2:
        return "No valid arrangement"

    # If possible, we can arrange the string
    return ''.join([k * (max_count - (v - max_count) % 2) + v * ((v - max_count) // 2) for k, v in char_count.items()])

