    for count in char_count.values():
        if count > 2:
            return False  # If any character appears more than twice, it cannot be rearranged

    # Try rearranging the string
    for i in range(len(s)):
        for j in range(i + 1, len(s)):
            if s[i] == s[j]:
                # Swap adjacent characters
                s = s[:i] + s[j] + s[i+1:j] + s[j+1:]
                # Continue with the modified string
                break
        else:
            continue
        break
    else:
        # No valid rearrangement possible
        return 'No valid arrangement'

    return ''.join(sorted(s))

