def max_len_sub(arr, k):
    # Initialize a dictionary to keep track of the last occurrence index of each element
    d = {arr[0]: 0}

    # List to store indices of all numbers that can be included in the subsequence
    l = []

    # Iterate through the array starting from the second element
    for i in range(1, len(arr)):
        x = arr[i]
        # Find the number that would give the maximum length if inserted before current position
        y = x - k

        # If such a number exists and its last occurrence index is less than or equal to the current position minus one
        if y in d and d[y] <= (i - 1):
            # Replace the current index with this valid index to maximize the subsequence length
            d[x] = d[y]
        else:
            # Add the current index to the list as it cannot form a valid subsequence with the previous elements
            l.append(i)
            d[x] = i

    # Return the length of the longest subsequence found
    return len(l)

