def bell_number(n):
    """Find the number of ways to partition a set of n elements."""
    if n == 0:
        return 1
    else:
        bell = [0] * (n + 1)
        bell[0], bell[1] = 1, 1
        for i in range(2, n + 1):
            bell[i] = sum(bell[j - 1] for j in range(i))
        return bell[n]

# Test case to verify the solution
