def comb_sort(arr):
    # Initial gap size is len(arr)
    gap = len(arr)

    # Initialize shrink factor
    shrink_factor = 1.3

    # Continue sorting while the gap is more than 1 or swapped
    while gap > 1:
        gap = int(gap / shrink_factor)  # Reduce the gap by the shrink factor

        for i in range(0, len(arr) - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]  # Swap elements

# Example test case
