def count_Squares(m, n):
    # Ensure m is always less than or equal to n to avoid confusion
    if m > n:
        m, n = n, m

    total_squares = 0
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            # Calculate the area of the square formed by (i, j)
            square_area = i * j
            # Add the square area to the total
            total_squares += square_area

    return total_squares

