def sequence(n):
    # Initialize the first two numbers of the Newman-Conway sequence
    c = [1, 1]

    # Generate the rest of the sequence up to the nth term
    while len(c) < n:
        temp = c[-2] + c[-1]
        if temp >= len(c):
            c.append(temp)
        else:
            c.append(c[temp])

    return c[n - 1]

# Example usage:
print(sequence(10))  # Output: 6

