def next_smallest_palindrome(n):
    # Convert n to string and reverse it to get the reversed version of n
    reversed_n = str(n)[::-1]

    # If n is already a palindrome, increment by 1
    if reversed_n == str(n):
        return n + 1

    # Find the first non-palindromic digit from right to left
    for i in range(len(reversed_n) - 2, -1, -1):
        if reversed_n[i] < reversed_n[i + 1]:
            break

    # Increment the first non-palindromic digit found
    reversed_n[i] += 1

    # Zero out all digits to the right of this position
    reversed_n = reversed_n[:i+1] + '0' * (len(reversed_n) - i-1)

    # Convert the modified string back to an integer and return
    return int(reversed_n)

