def kth_element(arr, size, k):
    # If the k-th position is valid and within the array bounds
    if k >= 1 and k <= size:
        # Sort the array using a sorting algorithm (e.g., Bubble Sort)
        for i in range(size - 1): 
            for j in range(0, size - i - 1):  
                if arr[j] > arr[j + 1]:
                    arr[j], arr[j + 1] = arr[j + 1], arr[j] 
        # Return the k-th element in the sorted array
        return arr[k-1]
    else:
        return "Invalid input: k must be between 1 and the size of the array."

