def eulerian_num(n, m):
    """
    Calculate the Eulerian number a(n, m).

    Args:
    n (int): The upper limit of the sequence.
    m (int): The index for which the Eulerian number is needed.

    Returns:
    int: The Eulerian number a(n, m).
    """
    if m > n or n == 0:
        return 0
    elif m == 0:
        return 1
    else:
        # Using Binomial Coefficient formula
        return ((n - m) * eulerian_num(n - 1, m)) + (m + 1) * eulerian_num(n - 1, m - 1)

