def eulerian_num(n, m):
    # Base cases for small n and m values
    if n == 0 and m == 0:
        return 1
    elif n == 1 or m == 1 or m > n:
        return 0

    # Recursive computation of Eulerian number using dynamic programming
    # dp[n][m] represents the number of permutations of length n with m inversions
    dp = [[0 for _ in range(m + 1)] for _ in range(n + 1)]

    # Initialize base cases
    for i in range(n + 1):
        dp[i][0] = 1

    for i in range(1, n + 1):
        for j in range(1, min(i, m) + 1):
            dp[i][j] = (dp[i - 1][j - 1] + i * dp[i - 1][j]) % 1000000007

    return dp[n][m]

# Test case to verify the correctness of the function
assert eulerian_num(3, 1) == 4

