def check_integer(s):
    # Check if the input is an empty string
    if s == "":
        return False

    # Check for leading zeros if it's positive
    if s[0] == "+" and s[1:].startswith("0"):
        return False

    # Check for negative numbers
    if s.startswith("-"):
        return s[1:].isdigit()

    # If all checks pass, the number is considered valid
    return s.isdigit()

