def check_triplet(arr, target_sum):
    arr.sort()  # Sort the array first to make it easier to find triplets
    n = len(arr)

    for i in range(n - 2):  # Iterate till n-2 because we need three elements
        left = i + 1
        right = n - 1

        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]

            if current_sum == target_sum:
                return True  # Found a triplet with the given sum
            elif current_sum < target_sum:
                left += 1  # Move the left pointer to increase the sum
            else:
                right -= 1  # Move the right pointer to decrease the sum

    return False  # No triplet found with the given sum

