    # Initialize variables for the Fibonacci sequence and the smart numbers list
    fib_sequence = [0, 1]
    smart_numbers = [0, 2]

    # Generate Fibonacci numbers until we have enough to get the nth smart number
    while len(smart_numbers) < n:
        next_fib = fib_sequence[-1] + fib_sequence[-2]
        if next_fib >= 30:  # Stop generating numbers if they exceed 30 (the smallest smart number)
