        fib_sequence.append(next_fib)

        # Check if the current Fibonacci number is a smart number
        is_smart = True
        for i in range(2, int(fib_sequence[-1]**0.5) + 1):
            if fib_sequence[-1] % i == 0:
                is_smart = False
                break
        if is_smart:
            smart_numbers.append(fib_sequence[-1])

    return smart_numbers[n-1]

