def find_divisors(n):
    # Find divisors of n and return them as a list
    divisors = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:  # Avoid adding square root twice if n is a perfect square
                divisors.append(n // i)
    return sorted(divisors)

def is_amicable(a, b):
    # Check if two numbers are amicable
    return sum(find_divisors(a)) == b and sum(find_divisors(b)) == a

