def find_length(s, n):
    max_diff = 0
    left = 0
    zero_count = 0
    one_count = 0

    for right in range(n):
        if s[right] == '0':
            zero_count += 1
        else:
            one_count += 1

        current_diff = abs(zero_count - one_count)

        # Update the maximum difference found so far
        max_diff = max(max_diff, current_diff)

        # If the difference exceeds half of the length of the string, move the left pointer
        while (zero_count + one_count) > n / 2:
            if s[left] == '0':
                zero_count -= 1
            else:
                one_count -= 1
            left += 1

    return max_diff

