def check_last(arr, p, x):
    # Check if the first element of the array is equal to x
    if arr[0] == x:
        return "EVEN"

    # Perform the operation p times on the array
    for _ in range(p):
        for i in range(len(arr)):
            # If the current element is odd, double it; otherwise, divide it by 2
            if arr[i] % 2 != 0:
                arr[i] *= 2
            else:
                arr[i] //= 2

    # Check the last element of the modified array
    return "EVEN" if arr[-1] % 2 == 0 else "ODD"

