def count_samepair(list1, list2, list3):
    # Use set intersection to find common elements across all lists
    common_elements = set(list1) & set(list2) & set(list3)

    # Count the number of occurrences of each element in the common set
    counts = {element: list1.count(element) for element in common_elements}

    # Return the total count of unique pairs
    return sum(count * (count - 1) // 2 for count in counts.values())

