    # Use dictionary to keep track of occurrences of each number in all lists
    count_dict = {}

    for num in a + b + c:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1

    # Count pairs where count is greater than 1
    return sum(count // 2 for count in count_dict.values())

