    # Base case: if we've reached the bottom of the triangle
    if row_index == len(triangle) - 1:
        return triangle[row_index][col_index]

    # Recursively move to the next row and add the minimum of the two possible paths
    return triangle[row_index][col_index] + min(max_path_sum(triangle, row_index+1, col_index), max_path_sum(triangle, row_index+1, col_index+1))

