def sum_digits_twoparts(n):
    # Calculate the total number of digits
    num_digits = len(str(n))

    # If there's only one digit, return it as the result
    if num_digits == 1:
        return (n, n)

    # Initialize the two parts with equal sum of digits
    part1 = int(str(n)[0])
    part2 = 9 * (num_digits - 1) + sum_digits(part1)

    return (part1, part2)

