def longest_subseq_with_diff_one(arr, n):
    # Create a dp table where dp[i] represents the length of the longest subsequence ending at index i
    dp = [1] * n

    # Iterate over the array starting from the second element
    for i in range(1, n):
        # Check if the current element is one more than the previous element
        if arr[i] - arr[i - 1] == 1:
            dp[i] = dp[i - 1] + 1

    # Return the maximum value in the dp table which is the length of the longest subsequence with the desired property
    return max(dp)

