    dp = [[0] * (n + 1) for _ in range(n)]

    for i in range(1, n):
        if arr[i] - arr[i-1] == 1:
            dp[i][i+1] = dp[i-1][i]
            dp[i][i+2] = dp[i-1][i] + 1
        else:
            dp[i][i+1] = max(dp[i-1][i], dp[i-1][i+1])

    return max(dp[n-1])

