    # Initialize dp table where dp[i][j] represents the length of the longest subsequence with a difference of j 
    dp = [[0] * (n + 2) for _ in range(n)]

    # Iterate through the array and update the dp table
    for i in range(1, n):
        for j in range(1, n + 2):
            if abs(arr[i] - arr[i-1]) == j:
                dp[i][j] = 1 + dp[i-1][j]
            else:
                dp[i][j] = max(dp[i-1][j], dp[i-1][j-1])

    # The result is stored in dp[n][n+1]
    return dp[n][n+1]

