def is_coprime(x, y):
    # Check if both numbers are greater than 0 and less than 2
    if x <= 0 or y <= 0 or x >= 2 or y >= 2:
        return False

    # Calculate the greatest common divisor (GCD)
    for i in range(2, min(x, y) + 1):
        if x % i == 0 and y % i == 0:
            return False

    # If no common factors are found, the numbers are coprime
    return True

