def next_Power_Of_2(n):
    # Check if n is already a power of 2
    if (n & (n - 1)) == 0:
        return n

    # Find the next highest power of 2
    i = 1
    while True:
        if (i << 1) <= n:
            i <<= 1
        else:
            break
    return i

