def get_pell(n):
    # Base cases for Pell numbers
    if n == 0:
        return 0
    elif n == 1:
        return 1

    # Initialize variables for the first two Pell numbers
    a, b = 0, 1

    # Calculate the nth Pell number iteratively
    for _ in range(2, n + 1):
        a, b = b, 2 * b + a

    return b

