def is_valid_parentheses(s):
    # Define pairs of parentheses
    matching_parens = {')': '(', '}': '{', ']': '['}

    # List to keep track of opening parentheses
    stack = []

    # Iterate through each character in the string
    for char in s:
        # If it's an opening parenthesis, push it onto the stack
        if char in matching_parens.values():
            stack.append(char)
        # If it's a closing parenthesis
        elif char in matching_parens.keys():
            # If the stack is empty or the top doesn't match the corresponding opening parenthesis, return False
            if not stack or stack.pop() != matching_parens[char]:
                return False

    # If the stack is empty at the end, all parentheses were matched correctly; otherwise, return False
    return len(stack) == 0

