    for i in range(start + 1, end + 1):
        for j in range(i + 1, end + 1):
            # Check if the product of the pair equals the lcm of the pair
            if i * j == find_lcm(i, j):
                return (i, j)
    return None

def find_lcm(a, b):
    # Calculate the least common multiple using the formula: lcm(a, b) = abs(a*b) / gcd(a, b)
    from math import gcd
    return abs(a*b) // gcd(a, b)

