def common_prefix(strs, n):
    # If no strings, return empty string
    if not strs:
        return ""

    # Find the minimum length among all strings
    min_len = min(len(s) for s in strs)

    # Iterate through each character up to the minimum length
    for i in range(min_len):
        # Check if the character at index i is the same in all strings
        if all(strs[j][i] == strs[0][i] for j in range(1, n)):
            continue
        else:
            # Return the prefix up to the current index
            return strs[0][:i]

# Example usage:
