    # Initialize a dictionary to store frequency of elements
    freq = {}

    # Count the frequency of each element in the array
    for i in arr:
        if i in freq:
            freq[i] += 1
        else:
            freq[i] = 1

    # Initialize the counter for pairs
    counter = 0

    # Iterate through the dictionary to find pairs with difference k
    for i in freq.keys():
        # Check if there is another element with the same value as i + k
        if i + k in freq:
            # Add the minimum of the frequencies of both elements to the counter
            counter += min(freq[i], freq[i + k])

    return counter

