def first_Missing_Positive(nums, n):
    # Iterate through the array and place each element at its correct position
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i]-1] != nums[i]:
            # Swap the current element with the element at its correct position
            nums[nums[i]-1], nums[i] = nums[i], nums[nums[i]-1]

    # Find the first index where the element is not at its correct position
    for i in range(n):
        if nums[i] != i+1:
            return i+1

    # If all elements are in their correct positions, return n+1
    return n+1

