def find_exponentio(tuple1, tuple2):
    # Initialize an empty list to store the results
    result = []
    # Iterate over the elements of both tuples using zip for parallel iteration
    for x, y in zip(tuple1, tuple2):
        # Calculate the power and append it to the result list
        result.append(x ** y)
    # Return the list of results as a tuple
    return tuple(result)

