def find_longest_repeating_subseq(string):
    n = len(string)

    # Create a table to store results of subproblems
    lookup_table = [[0 for i in range(n+1)] for j in range(n+1)]

    # Fill lookup_table in bottom-up manner
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if string[i-1] == string[j-1] and i != j:
                lookup_table[i][j] = lookup_table[i-1][j-1] + 1
            else:
                lookup_table[i][j] = max(lookup_table[i-1][j], lookup_table[i][j-1])

    return lookup_table[n][n]

