def count_Num(n):
    count = 0
    # Count the number of bits where both 0th and n-th bits are set.
    while n > 0:
        # Check if the 0th bit is set.
        if n & 1:
            # Check if the n-th bit is set.
            if (n >> (n - 1)) & 1:
                count += 1
        # Move to the next bit.
        n >>= 1
    return count

