def sort_on_occurence(tuples_list):
    # Count occurrences of each tuple's first element
    counts = {}
    for tup in tuples_list:
        if tup[0] in counts:
            counts[tup[0]].append(tup)
        else:
            counts[tup[0]] = [tup]

    # Sort the lists by their first elements and then by their indices
    sorted_tuples = []
    for key in sorted(counts.keys()):
        sorted_tuples.extend(sorted(counts[key], key=lambda x: (x.index(key), x)))

    return sorted_tuples

