    # Initialize a table of size (len(s) x len(s)) with 0s
    dp = [[0 for _ in range(len(s))] for _ in range(len(s))]

    # Fill the table
    for i in range(1, len(s)+1):
        for j in range(1, len(s)+1):
            if s[i-1] == reversed_s[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

