def lps(s):
    n = len(s)

    # Create a table to store results of substring problems.
    dp = [[0 for x in range(n)] for y in range(n)]

    # Strings of length 1 are palindrome of length 1
    for i in range(n):
        dp[i][i] = 1

    # Build the table. Note that the diagonal entries are already filled (length=1).
    for cl in range(2, n+1):
        for start in range(0, n-cl+1):
            end = start + cl - 1
            if s[start] == s[end]:
                dp[start][end] = 2 + dp[start+1][end-1]
            else:
                dp[start][end] = max(dp[start+1][end], dp[start][end-1])

    # The value at dp[0][n-1] will be our result
    return dp[0][n-1]

