def count_Primes_nums(n):
    """
    Counts the number of prime numbers less than n.

    Args:
    n (int): A non-negative integer.

    Returns:
    int: The count of prime numbers less than n.
    """
    if n <= 1:
        return 0

    primes = []

    for num in range(2, n):
        is_prime = True
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)

    return len(primes)

