def newman_prime(n):
    """
    Return the n-th Newman-Shanks-Williams prime number.

    Args:
    - n: An integer representing the position of the prime number to find.

    Returns:
    - The n-th Newman-Shanks-Williams prime number as an integer.
    """
    if n <= 0:
        return None  # Invalid input

    def sieve_of_eratosthenes(limit):
        primes = [True] * (limit + 1)
        p = 2
        while (p * p <= limit):
            if primes[p]:
                for i in range(p * p, limit + 1, p):
                    primes[i] = False
            p += 1
        return [i for i in range(2, limit + 1) if primes[i]]

    def next_newman_prime():
        current = 2
        count = 1
        while True:
            if all((current % i != 0 for i in range(2, int(current**0.5) + 1))):
                yield current
            current += 1

    primes = sieve_of_eratosthenes(1_000_000)

