def get_Position(arr, n, k):
    # Initialize pointers for left and right bounds
    l = 0
    r = n - 1

    while l <= r:
        mid = (l + r) // 2

        # Check if the target is found at the middle
        if arr[mid] == k:
            r = mid - 1  # Move right pointer to the left
        elif arr[mid] < k:
            l = mid + 1  # Move left pointer to the right
        else:
            r -= 1  # Decrease right pointer to continue searching

    return l  # Return the index of the last occurrence of k

