def get_Position(arr, length, k):
    # Use binary search to find the index of the first occurrence of 'k'
    left, right = 0, length - 1
    first_occurrence_index = -1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == k:
            first_occurrence_index = mid
            right = mid - 1  # Move left to find the last occurrence
        elif arr[mid] < k:
            left = mid + 1
        else:
            right = mid - 1

    # If k is not found, return -1
    if first_occurrence_index == -1:
        return -1

    # The last occurrence of k will be at the same position as the first occurrence
    last_occurrence_index = first_occurrence_index
    return last_occurrence_index

