def max_sum_increasing_subseq(nums, i, k):
    if i < 0 or k < i + 1:
        return 0

    # Initialize a list with zeros of length k+1
    dp = [0] * (k + 1)

    # Fill the DP table
    for j in range(i + 1, len(nums)):
        for l in range(1, k + 1):
            if nums[j] > nums[l - 1]:
                dp[l] = max(dp[l], dp[l - 1] + nums[j])

    # The result will be the value at dp[k]
