def set_left_most_unset_bit(number):
    # Initialize the result to be zero
    result = 0

    # Loop through each bit of the number
    while number > 0:
        # If the least significant bit is unset (i.e., it is 0)
        if not (number & 1):
            return result | (1 << ((result + 1) % 64))
        # Move to the next bit and increment result by one
        result += 1
        number >>= 1

    # If all bits were set, then set the leftmost unset bit
    if number == 0:
        return result | 1

    return result

