def find_last_occurrence(arr, target):
    # Use binary search to find the last occurrence
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] < target:
            left = mid + 1
        elif arr[mid] > target:
            right = mid - 1
        else:
            # If the middle element is equal to the target, move right pointer
            left = mid + 1

    # If 'right' points to the next position after the last occurrence, return -1
    return right if right != len(arr) else -1

