def get_Min_Squares(n):
    # Base cases
    if n == 0:
        return 0
    if n < 4:
        return n

    # Initialize result to infinity
    min_squares = float('inf')

    # Loop through possible square roots starting from 1
    for i in range(1, int(n**0.5) + 1):
        # Recursively call the function with remaining value after subtracting the current square
        res = get_Min_Squares(n - i*i)

        # Update the minimum number of squares found so far
        if res + 1 < min_squares:
            min_squares = res + 1

    return min_squares

