def find_Divisor(a, b):
    # Initialize a dictionary to keep track of divisor counts
    divisor_count = {}

    # Iterate through all numbers from a to b (inclusive)
    for number in range(a, b + 1):
        # Find all divisors of the current number and increment their count
        for i in range(1, int(number ** 0.5) + 1):
            if number % i == 0:
                divisor_count[i] = divisor_count.get(i, 0) + 1
                divisor_count[number // i] = divisor_count.get(number // i, 0) + 1

    # Find the maximum divisor count
    max_divisor_count = max(divisor_count.values(), default=0)

    # Return the divisor with the maximum count
    for divisor, count in divisor_count.items():
        if count == max_divisor_count:
            return divisor

# Example usage
