def find_minimum_range(arrays):
    # Initialize variables to track the minimum and maximum values found across all arrays
    min_val = float('inf')
    max_val = float('-inf')

    # Iterate over each array to find the minimum and maximum values
    for arr in arrays:
        if arr[0] < min_val:
            min_val = arr[0]
        if arr[-1] > max_val:
            max_val = arr[-1]

    # The smallest range is the difference between the maximum and minimum values
    return (min_val, max_val)

