def count_odd_squares(start, end):
    # Initialize a counter for squares with odd factors
    odd_factor_count = 0

    # Loop through each number in the range [start, end]
    for num in range(start, end + 1):
        # Check if the square of the number has only one distinct prime factor (which is itself)
        if len(prime_factors(num)) == 1:
            odd_factor_count += 1

    return odd_factor_count

# Helper function to get prime factors of a number
def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

