def first_Element(arr,k):
    """
    Given an integer array arr and an integer k, return the first 
    element that occurs k times in the array.

    Parameters:
    arr (list): The input array of integers.
    k (int): The number of occurrences of the desired element.

    Returns:
    int: The first element with k occurrences, or -1 if no such element exists.
    """
    count_map = {}
    for i in arr:
        if i in count_map:
            count_map[i] += 1
        else:
            count_map[i] = 1

    for key, value in count_map.items():
        if value == k:
            return key
    return -1

