def min_flip_to_make_string_alternate(s):
    # Find the position where the first character is different from its neighbor
    for i in range(1, len(s)):
        if s[i] != s[i-1]:
            break
    else:
        return 0  # The string is already alternating

    # Count the flips needed to change the string to alternating starting from the found index
    count = 0
    for i in range(i+1, len(s), 2):
        if s[i] != '1':
            count += 1
    for i in range(i, len(s), 2):
        if s[i] != '0':
            count += 1

    return min(count, len(s)-count)

# Test cases
