    # If there is no missing element, return n+1
    if arr[end] - arr[start] + 1 == end - start + 1:
        return end + 1

    # Perform binary search
    while start <= end:
        mid = (start + end) // 2

        # Check if the next number is present at the index mid
        if arr[mid] != mid + start:
            return mid + start

        # If the element is at its correct position, search in the right half
        elif arr[mid] < mid + start:
            start = mid + 1
        else:
            end = mid - 1

    return end + 1

