    if nums[mid] != mid + 1:
        return mid + 1

    # Recursively search in the left half
    if nums[mid] == mid:
        return smallest_missing(nums, start, mid - 1)

    # Otherwise, the missing number is in the right half
    return smallest_missing(nums, mid + 1, end)

