def round_num(num, multiple):
    # Find the nearest lower multiple of 'multiple'
    lower_multiple = (num // multiple) * multiple
    # Check if it's closer to 'lower_multiple' or 'higher_multiple'
    higher_multiple = lower_multiple + multiple

    # Determine which one is closer to 'num' and return it
    if abs(num - lower_multiple) < abs(num - higher_multiple):
        return lower_multiple
    else:
        return higher_multiple

