def add_nested_tuples(tuple1, tuple2):
    # Initialize the result as an empty list
    result = []

    # Iterate over each tuple in both input tuples
    for sub_tuple1, sub_tuple2 in zip(tuple1, tuple2):
        # Perform element-wise addition and append to the result list
        result.append(tuple(map(lambda x, y: x + y, sub_tuple1, sub_tuple2)))

    return tuple(result)

