def add_nested_tuples(tuple1, tuple2):
    result = []
    for inner_list1, inner_list2 in zip(tuple1, tuple2):
        # Ensure both lists have the same length or pad shorter list with zeros
        if len(inner_list1) < len(inner_list2):
            inner_list1 += [0] * (len(inner_list2) - len(inner_list1))
        elif len(inner_list2) < len(inner_list1):
            inner_list2 += [0] * (len(inner_list1) - len(inner_list2))

        # Perform element-wise addition
        added_list = [x + y for x, y in zip(inner_list1, inner_list2)]
        result.append(added_list)

    return tuple(result)

