def rearrange_bigger(n):
    # Convert the integer to a list of its digits
    digits = list(str(n))

    # Iterate through the list from right to left
    for i in range(len(digits) - 2, -1, -1):
        # Check if the current digit is less than the digit immediately after it
        if digits[i] < digits[i + 1]:
            # Find the smallest digit in the remaining part of the list that is greater than digits[i]
            min_digit_index = i + 1
            for j in range(i + 2, len(digits)):
                if digits[j] > digits[i] and digits[j] < digits[min_digit_index]:
                    min_digit_index = j

            # Swap the found digits
            digits[i], digits[min_digit_index] = digits[min_digit_index], digits[i]

            # Sort the digits after the swapped position
            digits[i+1:] = sorted(digits[i+1:])

            # Convert the list of digits back to an integer
            return int(''.join(digits))

    # If no such arrangement exists, return None
    return None

