def group_tuples(tuples_list):
    # Initialize an empty dictionary to store grouped elements
    grouped_elements = {}

    # Iterate over each tuple in the list
    for tup in tuples_list:
        # Check if the current tuple's first element is already in the dictionary
        if tup[0] not in grouped_elements:
            # If not, add it with the current tuple as its value
            grouped_elements[tup[0]] = [tup]
        else:
            # If it is, append the current tuple to the existing list of values
            grouped_elements[tup[0]].append(tup)

    # Return the list of lists containing common first elements
    return list(grouped_elements.values())

