def count_bidirectional(tuples):
    # Create a set from the first element of each tuple and another from the second element
    first_elements = set(tuple[0] for tuple in tuples)
    second_elements = set(tuple[1] for tuple in tuples)

    # Initialize a counter
    count = 0

    # Iterate over all combinations of elements from the two sets
    for first in first_elements:
        for second in second_elements:
            # If both elements form a bidirectional pair, increment the counter
            if (first, second) in tuples and (second, first) in tuples:
                count += 1

    # Return the total count of bidirectional tuple pairs
    return str(count)

