    # Count the occurrences for each element in the first list
    for element in lst:
        if element in result:
            result[element] += 1
        else:
            result[element] = 1

    # Use list comprehension to filter out elements not in the first list
    filtered_result = [element for element, count in result.items() if element in lst1]

