def cal_sum(n):
    # Initialize the first three Perrin numbers
    p1 = 3
    p2 = 0
    p3 = 2

    total_sum = 0
    for i in range(n):
        total_sum += p1
        # Calculate next three Perrin numbers
        p1, p2, p3 = p2, p3, p1 + p2

    return total_sum

# Test case
assert cal_sum(9) == 49

