def check_Triangle(x,y,z,x1,y1,z1,x2,y2,z2):
    # Calculate lengths of sides
    side1 = ((x - x1)**2 + (y - y1)**2 + (z - z1)**2)**0.5
    side2 = ((x - x2)**2 + (y - y2)**2 + (z - z2)**2)**0.5
    side3 = ((x - x3)**2 + (y - y3)**2 + (z - z3)**2)**0.5

    # Check if all sides are less than the sum of the other two sides
    if side1 < side2 + side3 and side2 < side1 + side3 and side3 < side1 + side2:
        return 'Yes'
    else:
        return 'No'

