def check_Triangle(a, b, c, d, e, f):
    # Sort the list of points to simplify comparisons
    points = sorted([a, b, c, d, e, f])

    # Check for validity based on the Triangle Inequality Theorem
    if points[0] + points[1] > points[2]:
        if points[3] + points[4] > points[5]:
            if points[0] + points[3] > points[4]:
                return 'Yes'
    return 'No'

