def max_product(nums):
    if len(nums) < 2:
        return nums[0]  # If there are less than two elements, the product is the single element

    dp = [num for num in nums]

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], nums[i] * dp[j])

    return max(dp)

