# Function to calculate the greatest common divisor (GCD) of two numbers
def gcd(a, b):
    # Base case: if the second number is zero, return the first number as GCD
    if b == 0:
        return a
    # Recursive case: call gcd with second and remainder of first divided by second
    else:
        return gcd(b, a % b)

# Example usage
print(gcd(12, 17))  # Output: 1

