def num_comm_div(a, b):
    # Initialize the smallest possible divisor as 1
    comm_div = 1

    # Iterate from 1 to the minimum of a and b
    for i in range(1, min(a, b) + 1):
        # If both numbers are divisible by i, it is a common divisor
        if a % i == 0 and b % i == 0:
            comm_div = i

