def factorial(n):
    if n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n-1)

def permutation_coefficient(n, k):
    # Check if the values are non-negative integers
    if not (isinstance(n, int) and isinstance(k, int)):
        raise ValueError("Both n and k must be non-negative integers.")

    # Check if k is less than or equal to n
    if k > n:
        raise ValueError("k cannot be greater than n.")

    # Calculate the permutation coefficient using the formula: P(n, k) = n! / (n-k)!
    return factorial(n) // factorial(n-k)

